/* ==========================================
   APP INITIALIZATION
========================================== */

document.addEventListener("DOMContentLoaded", () => {

    const header = document.querySelector(".header");
    const hamburger = document.querySelector(".hamburger");
    const navMenu = document.querySelector(".nav-menu");
    const navLinks = document.querySelectorAll(".nav-link");
    const sections = document.querySelectorAll("section");
    const progressBar = document.getElementById("progress-bar");
    const loader = document.getElementById("loader");
    const dot = document.querySelector(".cursor-dot");
    const ring = document.querySelector(".cursor-ring");

    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const isCoarsePointer = window.matchMedia("(pointer: coarse)").matches;

    /* ==========================================
       LOADER — fast hide, session-aware
    ========================================== */

    if (loader) {
        if (sessionStorage.getItem("loaderShown")) {
            loader.classList.add("hide");
        } else {
            sessionStorage.setItem("loaderShown", "true");
            setTimeout(() => loader.classList.add("hide"), 900);
        }
    }

    /* ==========================================
       MOBILE MENU
    ========================================== */

    const setMenuOpen = (open) => {
        if (!hamburger || !navMenu) return;
        hamburger.classList.toggle("active", open);
        navMenu.classList.toggle("active", open);
        hamburger.setAttribute("aria-expanded", String(open));
        document.body.style.overflow = open ? "hidden" : "";
    };

    if (hamburger && navMenu) {
        hamburger.addEventListener("click", () => {
            setMenuOpen(!navMenu.classList.contains("active"));
        });
    }

    navLinks.forEach((link) => {
        link.addEventListener("click", () => setMenuOpen(false));
    });

    document.addEventListener("click", (e) => {
        if (!e.target.closest(".navbar")) {
            setMenuOpen(false);
        }
    });

    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") {
            setMenuOpen(false);
        }
    });

    /* ==========================================
       SCROLL — single rAF-throttled handler
    ========================================== */

    let scrollTicking = false;

    const onScroll = () => {
        const scrollY = window.scrollY;

        if (header) {
            header.classList.toggle("scrolled", scrollY > 50);
        }

        if (progressBar) {
            const scrollHeight =
                document.documentElement.scrollHeight -
                document.documentElement.clientHeight;
            const progress = scrollHeight > 0
                ? Math.round((scrollY / scrollHeight) * 100)
                : 0;
            progressBar.style.width = `${progress}%`;
            progressBar.setAttribute("aria-valuenow", String(progress));
        }

        let current = "";
        sections.forEach((section) => {
            if (scrollY >= section.offsetTop - 120) {
                current = section.getAttribute("id");
            }
        });

        navLinks.forEach((link) => {
            link.classList.toggle("active", link.getAttribute("href") === `#${current}`);
        });
    };

    window.addEventListener("scroll", () => {
        if (!scrollTicking) {
            scrollTicking = true;
            requestAnimationFrame(() => {
                onScroll();
                scrollTicking = false;
            });
        }
    }, { passive: true });

    onScroll();

    /* ==========================================
       CUSTOM CURSOR — desktop only
    ========================================== */

    if (dot && ring && !isCoarsePointer && !prefersReducedMotion) {
        let cursorX = 0;
        let cursorY = 0;
        let ringX = 0;
        let ringY = 0;
        let cursorTicking = false;

        document.addEventListener("mousemove", (e) => {
            cursorX = e.clientX;
            cursorY = e.clientY;

            dot.style.transform = `translate(${cursorX}px, ${cursorY}px) translate(-50%, -50%)`;

            if (!cursorTicking) {
                cursorTicking = true;
                requestAnimationFrame(function animateRing() {
                    ringX += (cursorX - ringX) * 0.18;
                    ringY += (cursorY - ringY) * 0.18;
                    ring.style.transform = `translate(${ringX}px, ${ringY}px) translate(-50%, -50%)`;

                    if (Math.abs(cursorX - ringX) > 0.8 || Math.abs(cursorY - ringY) > 0.5) {
                        requestAnimationFrame(animateRing);
                    } else {
                        cursorTicking = false;
                    }
                });
            }
        }, { passive: true });

        document.querySelectorAll("a, button, .glass-card, .skill-pill").forEach((item) => {
            item.addEventListener("mouseenter", () => ring.classList.add("cursor-hover"));
            item.addEventListener("mouseleave", () => ring.classList.remove("cursor-hover"));
        });
    } else if (dot && ring) {
        dot.style.display = "none";
        ring.style.display = "none";
    }

    /* ==========================================
       SCROLL REVEAL — Intersection Observer
    ========================================== */

    if (!prefersReducedMotion) {

        const fadeElements = document.querySelectorAll(".fade-up:not(.active)");

        const fadeObserver = new IntersectionObserver(
            (entries, observer) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add("active");
                        observer.unobserve(entry.target);
                    }
                });
            },
            { threshold: 0.1 }
        );

        fadeElements.forEach((element) => fadeObserver.observe(element));

    } else {
        document.querySelectorAll(".fade-up").forEach((el) => {
            el.classList.add("active");
        });
    }

    /* ==========================================
       LAZY IMAGES — native + fallback
    ========================================== */

    document.querySelectorAll("img[loading='lazy']").forEach((img) => {
        img.decoding = "async";
    });

});


/* ==========================================================
   WEB3FORMS CONTACT FORM
   ========================================================== */

const contactForm = document.getElementById("contactForm");
const submitBtn = document.getElementById("submitBtn");
const successModal = document.getElementById("successModal");
const closeModal = document.getElementById("closeModal");

if (contactForm) {

    contactForm.addEventListener("submit", async (e) => {

        e.preventDefault();

        submitBtn.disabled = true;

        submitBtn.innerHTML = `
            <i class="fas fa-spinner fa-spin"></i>
            Sending...
        `;

        const formData = new FormData(contactForm);

        try {

            const response = await fetch(
                "https://api.web3forms.com/submit",
                {
                    method: "POST",
                    body: formData
                }
            );

            const result = await response.json();

            if (result.success) {

                contactForm.reset();

                successModal.classList.add("show");
                closeModal?.focus();

                submitBtn.innerHTML = `
                    <i class="fas fa-check"></i>
                    Sent Successfully
                `;

                setTimeout(() => {

                    submitBtn.disabled = false;

                    submitBtn.innerHTML = `
                        <span class="btn-text">
                            Send Message
                        </span>
                    `;

                }, 2000);

            }

            else{

                throw new Error(result.message);

            }

        }

        catch {

            submitBtn.disabled = false;

            submitBtn.innerHTML = `
                <i class="fas fa-triangle-exclamation"></i>
                Failed
            `;

            setTimeout(()=>{

                submitBtn.innerHTML = `
                    <span class="btn-text">
                        Send Message
                    </span>
                `;

            },2000);

            alert("Unable to send message. Please try again.");

        }

    });

}


/* ==========================================================
   CLOSE MODAL BUTTON
   ========================================================== */

if(closeModal){

    closeModal.addEventListener("click",()=>{

        successModal.classList.remove("show");

    });

}


/* ==========================================================
   CLICK OUTSIDE
   ========================================================== */

if(successModal){

    successModal.addEventListener("click",(e)=>{

        if(e.target===successModal){

            successModal.classList.remove("show");

        }

    });

}


/* ==========================================================
   ESC KEY
   ========================================================== */

document.addEventListener("keydown",(e)=>{

    if(e.key==="Escape"){

        if(successModal) successModal.classList.remove("show");

    }

});

/* ==========================================================
   TYPEWRITER — hero role cycling
   ========================================================== */

(function () {
    const roles = [
        "Software Developer",
        "Full-Stack Engineer",
        "AI Enthusiast",
        "Open Source Builder",
        "Problem Solver"
    ];

    const el = document.querySelector(".role-typed");
    if (!el) return;

    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (prefersReducedMotion) {
        el.textContent = roles[0];
        return;
    }

    let roleIdx = 0, charIdx = 0, deleting = false;

    function tick() {
        const current = roles[roleIdx];
        if (!deleting) {
            el.textContent = current.slice(0, ++charIdx);
            if (charIdx === current.length) {
                deleting = true;
                setTimeout(tick, 2000);
                return;
            }
            setTimeout(tick, 80);
        } else {
            el.textContent = current.slice(0, --charIdx);
            if (charIdx === 0) {
                deleting = false;
                roleIdx = (roleIdx + 1) % roles.length;
                setTimeout(tick, 300);
                return;
            }
            setTimeout(tick, 40);
        }
    }

    setTimeout(tick, 800);
})();


/* ==========================================================
   STAT COUNTER — count-up on scroll into view
   ========================================================== */

(function () {
    const stats = document.querySelectorAll(".stat-number[data-count]");
    if (!stats.length) return;

    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    function animateCount(el) {
        const target = parseInt(el.dataset.count, 10);
        const suffix = el.dataset.suffix || "";
        if (prefersReducedMotion) {
            el.textContent = target + suffix;
            return;
        }
        const duration = 1400;
        const start = performance.now();
        function step(now) {
            const progress = Math.min((now - start) / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            el.textContent = Math.round(eased * target) + suffix;
            if (progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
        el.closest(".stat-card").classList.add("counted");
    }

    const observer = new IntersectionObserver(
        (entries, obs) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    animateCount(entry.target);
                    obs.unobserve(entry.target);
                }
            });
        },
        { threshold: 0.5 }
    );

    stats.forEach(el => observer.observe(el));
})();


/* ==========================================================
   FORM VALIDATION — real-time inline feedback
   ========================================================== */

(function () {
    const form = document.getElementById("contactForm");
    if (!form) return;

    function showError(groupId, errId, msg) {
        const group = document.getElementById(groupId);
        const err = document.getElementById(errId);
        if (!group || !err) return;
        group.classList.add("has-error");
        group.classList.remove("has-success");
        err.textContent = msg;
    }

    function showSuccess(groupId, errId) {
        const group = document.getElementById(groupId);
        const err = document.getElementById(errId);
        if (!group || !err) return;
        group.classList.remove("has-error");
        group.classList.add("has-success");
        err.textContent = "";
    }

    function validateName(val) {
        if (!val.trim()) return "Name is required.";
        if (val.trim().length < 2) return "Name must be at least 2 characters.";
        return "";
    }

    function validateEmail(val) {
        if (!val.trim()) return "Email is required.";
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)) return "Enter a valid email address.";
        return "";
    }

    function validateProject(val) {
        if (!val) return "Please select a project type.";
        return "";
    }

    function validateMessage(val) {
        if (!val.trim()) return "Message is required.";
        if (val.trim().length < 20) return `Message too short (${val.trim().length}/20 chars min).`;
        return "";
    }

    const nameInput = document.getElementById("contact-name");
    const emailInput = document.getElementById("contact-email");
    const projectInput = document.getElementById("contact-project");
    const msgInput = document.getElementById("contact-message");

    function bindValidation(input, groupId, errId, validator) {
        if (!input) return;
        input.addEventListener("blur", () => {
            const err = validator(input.value);
            if (err) showError(groupId, errId, err);
            else showSuccess(groupId, errId);
        });
        input.addEventListener("input", () => {
            if (document.getElementById(groupId).classList.contains("has-error")) {
                const err = validator(input.value);
                if (err) showError(groupId, errId, err);
                else showSuccess(groupId, errId);
            }
        });
    }

    bindValidation(nameInput, "group-name", "err-name", validateName);
    bindValidation(emailInput, "group-email", "err-email", validateEmail);
    bindValidation(projectInput, "group-project", "err-project", validateProject);
    bindValidation(msgInput, "group-message", "err-message", validateMessage);

    // Full validate on submit attempt
    form.addEventListener("submit", function (e) {
        let valid = true;
        const checks = [
            [nameInput, "group-name", "err-name", validateName],
            [emailInput, "group-email", "err-email", validateEmail],
            [projectInput, "group-project", "err-project", validateProject],
            [msgInput, "group-message", "err-message", validateMessage]
        ];
        checks.forEach(([input, gid, eid, fn]) => {
            if (!input) return;
            const err = fn(input.value);
            if (err) { showError(gid, eid, err); valid = false; }
            else showSuccess(gid, eid);
        });
        if (!valid) e.stopImmediatePropagation();
    }, true); // capture phase so it runs before Web3Forms handler
})();

